I considering alternative method using timeout in thread.. I want to hear from your feedback.
attach the code below




import java.io.InputStream;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

import org.apache.tika.Tika;
import org.apache.tika.mime.MimeTypes;

public class TikaFileTypeDetector implements Callable&lt;String&gt;{

	private static final int TIMEOUT = 10;

	private final Tika tika = new Tika();

	private InputStream inputStream;

	private TikaFileTypeDetector(InputStream inputStream) {
		this.inputStream = inputStream;
	}

	@Override
	public String call() throws Exception {
		String mimetype = MimeTypes.OCTET_STREAM;

		mimetype = tika.detect(inputStream);
		return mimetype;
	}

	public static String detect(InputStream inputStream) {
		if(inputStream == null) {
			return null;
		}
		String mimetype = MimeTypes.OCTET_STREAM;

		TikaFileTypeDetector detector = new TikaFileTypeDetector(inputStream);
		ExecutorService executor = Executors.newSingleThreadExecutor();

		Future&lt;String&gt; future = executor.submit(detector);

        try {
        	mimetype = future.get(TIMEOUT, TimeUnit.SECONDS);
		} catch (InterruptedException e) {
			e.printStackTrace();
		} catch (ExecutionException e) {
			e.printStackTrace();
		} catch (TimeoutException e) {
			e.printStackTrace();
		} finally {
			executor.shutdownNow();
		}

        return mimetype;
	}

}

